{"tool": "write_file", "args": {"path": "summary.py", "content": "import networkx as nx


def summarize(edges):
    graph = nx.Graph()
    graph.add_edges_from(edges)
    summary_text = nx.info(graph)
    return {'nodes': graph.number_of_nodes(),
            'edges': graph.number_of_edges(),
            'text': summary_text}
